USE FraudLens;

SELECT COUNT(*) AS rows_with_null
FROM creditcard_transactions
WHERE 
    Time IS NULL
    OR v1 IS NULL
    OR v2 IS NULL
    OR v3 IS NULL
    OR v4 IS NULL
    OR v5 IS NULL
    OR v6 IS NULL
    OR v7 IS NULL
    OR v8 IS NULL
    OR v9 IS NULL
    OR v10 IS NULL
    OR v11 IS NULL
    OR v12 IS NULL
    OR v13 IS NULL
    OR v14 IS NULL
    OR v15 IS NULL
    OR v16 IS NULL
    OR v17 IS NULL
    OR v18 IS NULL
    OR v19 IS NULL
    OR v20 IS NULL
    OR v21 IS NULL
    OR v22 IS NULL
    OR v23 IS NULL
    OR v24 IS NULL
    OR v25 IS NULL
    OR v26 IS NULL
    OR v27 IS NULL
    OR v28 IS NULL
    OR Amount IS NULL
    OR Class IS NULL;  /*Thankfully, there are no nulls in any column for any row. We got zero.*/

SELECT Class, COUNT(*) FROM creditcard_transactions GROUP BY Class; /*We can see from this that class 0 (Non-Fraud) rows are 284315 in total and from class 1 (Fraud) are 492*/

SELECT Class, COUNT(*) AS cnt, COUNT(*) / (SELECT COUNT(*) FROM creditcard_transactions) * 100 AS pct FROM creditcard_transactions GROUP BY Class; /*This is a very imbalanced dataset, Class 0 = 99.8273 %  | Class 1 = 0.1727 % */


SELECT Class, AVG(V1), AVG(V2), AVG(V3), AVG(V4), AVG(V5), AVG(V6), AVG(V7), AVG(V8), AVG(V9), AVG(V10), AVG(V11), AVG(V12), AVG(V13), AVG(V14), AVG(V15), AVG(V16), AVG(V17), AVG(V18), AVG(V19), AVG(V20), AVG(V21), AVG(V22), AVG(V23), AVG(V24), AVG(V25), AVG(V26), AVG(V27), AVG(V28), AVG(Amount) FROM creditcard_transactions GROUP BY Class;

