/*
AVGS:

Now, just from the averages, the immediate thing I notice is that the avg of every column here of class 1 (Fraud) are significantly higher than every other column from class 0 (Non-Fraud).
*/
SELECT Class, STDDEV(V1), STDDEV(V2), STDDEV(V3), STDDEV(V4), STDDEV(V5), STDDEV(V6), STDDEV(V7), STDDEV(V8), STDDEV(V9), STDDEV(V10), STDDEV(V11), STDDEV(V12), STDDEV(V13), STDDEV(V14), STDDEV(V15), STDDEV(V16), STDDEV(V17), STDDEV(V18), STDDEV(V19), STDDEV(V20), STDDEV(V21), STDDEV(V22), STDDEV(V23), STDDEV(V24), STDDEV(V25), STDDEV(V26), STDDEV(V27), STDDEV(V28), STDDEV(Amount) FROM creditcard_transactions GROUP BY Class;

